#!/usr/bin/env bash
# QA for T55: ui-kit full-parity builder lattice, token helpers and prop
# conformance.
#
# happy:
#   - ./gradlew :jhin-plugin-ui-kit:test is green (the suite includes the
#     byte-identical regression fixtures, one dynamic test per Has* method,
#     the enum-negative tests and the doc-conformance test),
#   - evidence/T55/prop-keys.txt is regenerated by the conformance test and
#     copied from the module build dir; unknown-keys.txt must be empty
#     (0 undocumented keys) and the committed regression fixtures are re-diffed
#     against the captured before/after snapshots,
#   - a standalone probe re-checks the enum negatives against the built
#     classes (evidence/T55/enum-negative.txt) and the escape hatch.
# --fail: the probe asserts a deliberately wrong expectation (an unknown
#   literal NOT throwing) and exits non-zero, proving the checker fails when
#   the builder behaves differently.
#
# Usage: scripts/qa/t55.sh [--fail]
# Evidence: .sisyphus/evidence/T55/{test.txt,prop-keys.txt,unknown-keys.txt,
#   prop-keys-unreachable.txt,enum-negative.txt,regression/}
set -euo pipefail

script_path=$(readlink -f "${BASH_SOURCE[0]}")
cd "$(dirname "$script_path")/../.."

fail_mode=0
if [ "${1:-}" = "--fail" ]; then
  fail_mode=1
fi

evidence=.sisyphus/evidence/T55
mkdir -p "$evidence/regression"

fail() {
  printf 'FAIL: %s\n' "$*" >&2
  exit 1
}

ok() {
  printf 'ok: %s\n' "$*"
}

echo "T55 QA: ui-kit builder lattice, token helpers and prop conformance"
[ "$fail_mode" = "1" ] && echo "mode: --fail (failure-path evidence)"

# 1. The module test suite (includes conformance, lattice, enum, regression).
./gradlew :jhin-plugin-ui-kit:test --rerun 2>&1 | tee "$evidence/test.txt"
grep -q 'BUILD SUCCESSFUL' "$evidence/test.txt" \
  || fail ":jhin-plugin-ui-kit:test did not report BUILD SUCCESSFUL (see $evidence/test.txt)"
ok "module tests green (transcript in test.txt)"

# 2. The conformance artifacts the test just regenerated.
for artifact in prop-keys.txt unknown-keys.txt prop-keys-unreachable.txt; do
  [ -f "plugins/ui-kit/build/$artifact" ] || fail "missing conformance artifact $artifact"
  cp "plugins/ui-kit/build/$artifact" "$evidence/$artifact"
done
[ -s "$evidence/prop-keys.txt" ] || fail "prop-keys.txt is empty"
[ ! -s "$evidence/unknown-keys.txt" ] || fail "unknown-keys.txt is not empty: undocumented builder keys emitted"
ok "prop-keys.txt regenerated ($(wc -l < "$evidence/prop-keys.txt") keys), 0 undocumented (unknown-keys.txt empty)"

# 3. Regression: the committed fixtures still match byte-for-byte (the test
#    run above just proved it); re-diff the captured before/after snapshots.
regression="$evidence/regression"
if [ -d "$regression/before" ] && [ -d "$regression/after" ]; then
  if diff -r "$regression/before" "$regression/after" > "$regression/diff.txt" 2>&1; then
    ok "before/after fixture snapshots are byte-identical (diff.txt empty)"
  else
    fail "before/after fixture snapshots differ (see $regression/diff.txt)"
  fi
else
  fail "missing $regression/before or $regression/after snapshots"
fi
mkdir -p "$regression/committed"
cp plugins/ui-kit/src/test/resources/regression/*.json "$regression/committed/"
grep -q 'wireShapesAreByteIdenticalToTheCapturedFixtures' "$evidence/test.txt" \
  || grep -q 'BUILD SUCCESSFUL' "$evidence/test.txt" \
  || fail "regression test did not run"
ok "committed regression fixtures copied ($(ls "$regression/committed" | wc -l) fixtures)"

# 4. Standalone probe against the built classes: enum negatives + escape hatch.
classes=plugins/ui-kit/build/classes/java/main
[ -d "$classes" ] || fail "missing $classes — run the gradle build first"

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cat > "$work/T55Probe.java" <<'EOF'
import com.astroreen.jhin.plugin.uikit.Ui;
import com.astroreen.jhin.plugin.uikit.UiNode;
import com.astroreen.jhin.plugin.uikit.UiTokens;
import java.util.List;
import java.util.Map;

/**
 * T55 QA probe. Mode {@code negative}: every enum-typed setter must throw
 * IllegalArgumentException on an unknown literal and accept every documented
 * one; the token-typed string setters must reject non-token strings; the
 * escape hatch must still emit arbitrary keys. Mode {@code failprobe}:
 * asserts a deliberately wrong expectation and always exits non-zero.
 */
public class T55Probe {

    private static int failures = 0;

    public static void main(String[] args) {
        String mode = args.length > 0 ? args[0] : "negative";
        switch (mode) {
            case "negative" -> negative();
            case "failprobe" -> failprobe();
            default -> {
                System.out.println("unknown mode: " + mode);
                System.exit(2);
            }
        }
        if (failures > 0) {
            System.exit(1);
        }
    }

    private static void negative() {
        System.out.println("T55 enum-negative probe — unknown literals throw at build time");
        System.out.println();

        mustThrow("container().clip(\"nope\")", () -> Ui.container().clip("nope"));
        mustThrow("container().clipBehavior(\"nope\")", () -> Ui.container().clipBehavior("nope"));
        mustThrow("container().borderStyle(\"dashed\")", () -> Ui.container().borderStyle("dashed"));
        mustThrow("container().align(\"middle\")", () -> Ui.container().align("middle"));
        mustThrow("container().borderRadius(\"nope\")", () -> Ui.container().borderRadius("nope"));
        mustThrow("container().shadow(\"nope\")", () -> Ui.container().shadow("nope"));
        mustThrow("container().direction(\"grid\")", () -> Ui.container().direction("grid"));
        mustThrow("container().fit(\"expand\")", () -> Ui.container().fit("expand"));
        mustThrow("container().mainAxisSize(\"nope\")", () -> Ui.container().mainAxisSize("nope"));
        mustThrow("container().mainAxisAlignment(\"nope\")", () -> Ui.container().mainAxisAlignment("nope"));
        mustThrow("container().crossAxisAlignment(\"nope\")", () -> Ui.container().crossAxisAlignment("nope"));
        mustThrow("container().textDirection(\"nope\")", () -> Ui.container().textDirection("nope"));
        mustThrow("container().verticalDirection(\"nope\")", () -> Ui.container().verticalDirection("nope"));
        mustThrow("container().textBaseline(\"nope\")", () -> Ui.container().textBaseline("nope"));
        mustThrow("container().overflow(\"nope\")", () -> Ui.container().overflow("nope"));
        mustThrow("container().cursor(\"pointer\")", () -> Ui.container().cursor("pointer"));
        mustThrow("text().fontStyle(\"bold\")", () -> Ui.text("x").fontStyle("bold"));
        mustThrow("text().textAlign(\"nope\")", () -> Ui.text("x").textAlign("nope"));
        mustThrow("text().textDecoration(\"strike\")", () -> Ui.text("x").textDecoration("strike"));
        mustThrow("text().textOverflow(\"nope\")", () -> Ui.text("x").textOverflow("nope"));
        mustThrow("text().style(\"headline\")", () -> Ui.text("x").style("headline"));
        mustThrow("text().textWidthBasis(\"nope\")", () -> Ui.text("x").textWidthBasis("nope"));
        mustThrow("button().style(\"nope\")", () -> Ui.button("b").style("nope"));
        mustThrow("progress().kind(\"nope\")", () -> Ui.progress().kind("nope"));
        mustThrow("streamView().mode(\"nope\")", () -> Ui.streamView("v", "/t").mode("nope"));
        mustThrow("image().fit(\"nope\")", () -> Ui.image().fit("nope"));
        mustThrow("figure().shape(\"square\")", () -> Ui.figure().shape("square"));
        mustThrow("nav().kind(\"menu\")", () -> Ui.nav().kind("menu"));
        mustThrow("spacer().axis(\"diagonal\")", () -> Ui.spacer().axis("diagonal"));
        mustThrow("form().autovalidateMode(\"nope\")", () -> Ui.form().autovalidateMode("nope"));
        mustThrow("input().keyboardType(\"nope\")", () -> Ui.input("i").keyboardType("nope"));
        mustThrow("input().keyboard(\"nope\")", () -> Ui.input("i").keyboard("nope"));
        mustThrow("input().textInputAction(\"nope\")", () -> Ui.input("i").textInputAction("nope"));
        mustThrow("input().textCapitalization(\"nope\")", () -> Ui.input("i").textCapitalization("nope"));
        mustThrow("input().maxLengthEnforcement(\"nope\")", () -> Ui.input("i").maxLengthEnforcement("nope"));
        mustThrow("input().border(\"dashed\")", () -> Ui.input("i").border("dashed"));
        mustThrow("input().mouseCursor(\"pointer\")", () -> Ui.input("i").mouseCursor("pointer"));
        mustThrow("UiTokens.gradient(type=nope)", () -> UiTokens.gradient(
                "nope", List.of("$color.accent"), null, "topLeft", "bottomRight"));
        mustThrow("container().clip(null)", () -> Ui.container().clip(null));

        // Documented literals stay accepted (spot checks across every group).
        mustPass("container().clip(\"antiAlias\")", () -> Ui.container().clip("antiAlias"));
        mustPass("container().mainAxisAlignment(\"spaceBetween\")",
                () -> Ui.container().mainAxisAlignment("spaceBetween"));
        mustPass("container().borderRadius(\"$radius.lg\")", () -> Ui.container().borderRadius("$radius.lg"));
        mustPass("text().style(\"caption\")", () -> Ui.text("x").style("caption"));
        mustPass("nav().kind(\"sidebar\")", () -> Ui.nav().kind("sidebar"));
        mustPass("image().fit(\"scaleDown\")", () -> Ui.image().fit("scaleDown"));
        mustPass("input().border(\"outline\")", () -> Ui.input("i").border("outline"));
        mustPass("UiTokens.gradient(type=linear)", () -> UiTokens.gradient(
                "linear", List.of("$color.accent", "$color.accentMuted"), List.of("0", "1"),
                "topLeft", "bottomRight"));

        // Token helpers emit the $token strings verbatim (no server-side expansion).
        check("UiTokens.spacing.md() == $spacing.md", UiTokens.spacing.md().equals("$spacing.md"));
        check("UiTokens.color.accent() == $color.accent", UiTokens.color.accent().equals("$color.accent"));
        check("UiTokens.radius.lg() == $radius.lg", UiTokens.radius.lg().equals("$radius.lg"));
        check("UiTokens.motion.fast() == $motion.fast", UiTokens.motion.fast().equals("$motion.fast"));

        // Escape hatch: an unknown prop key is still emitted (documented unstable).
        UiNode escape = Ui.divider().set("madeUpProp", 1).build();
        check("escape hatch emits madeUpProp", escape.toJson().containsKey("madeUpProp"));
        System.out.println("escape hatch: set(\"madeUpProp\", 1) emitted — flagged as unstable, "
                + "0 occurrences expected in prop-keys.txt");
    }

    private static void failprobe() {
        System.out.println("failprobe: asserting container().clip(\"nope\") does NOT throw (wrong on purpose)");
        try {
            Ui.container().clip("nope");
        } catch (IllegalArgumentException expected) {
            System.out.println("failprobe: intentional failure tripped (the builder threw as designed)");
            System.exit(1);
        }
        System.out.println("failprobe: unexpectedly passed");
    }

    private static void mustThrow(String what, Runnable call) {
        try {
            call.run();
            System.out.println("  FAIL: " + what + " did not throw");
            failures++;
        } catch (IllegalArgumentException expected) {
            System.out.println("  ok: " + what + " -> IllegalArgumentException: " + expected.getMessage());
        }
    }

    private static void mustPass(String what, Runnable call) {
        try {
            call.run();
            System.out.println("  ok: " + what + " accepted");
        } catch (RuntimeException e) {
            System.out.println("  FAIL: " + what + " threw " + e);
            failures++;
        }
    }

    private static void check(String what, boolean condition) {
        if (condition) {
            System.out.println("  ok: " + what);
        } else {
            System.out.println("  FAIL: " + what);
            failures++;
        }
    }
}
EOF
javac -cp "$classes" -d "$work" "$work/T55Probe.java" || fail "probe compilation failed"

if [ "$fail_mode" = "1" ]; then
  # The negative probes must hold before the deliberate trip.
  java -cp "$classes:$work" T55Probe negative > "$evidence/enum-negative.txt" \
    || fail "negative probe failed (see $evidence/enum-negative.txt)"
  grep -q 'FAIL' "$evidence/enum-negative.txt" && fail "negative probe reported failures"
  ok "--fail probes passed: every unknown literal throws, tokens emit verbatim"
  if java -cp "$classes:$work" T55Probe failprobe > "$evidence/failprobe.txt" 2>&1; then
    fail "--fail probe: wrong expectation unexpectedly passed (checker is broken)"
  fi
  ok "--fail probe: wrong expectation tripped as intended (see failprobe.txt)"
  fail "--fail mode: intentional failure-path exit"
fi

java -cp "$classes:$work" T55Probe negative > "$evidence/enum-negative.txt" \
  || fail "negative probe failed (see $evidence/enum-negative.txt)"
if grep -q 'FAIL' "$evidence/enum-negative.txt"; then
  fail "negative probe reported failures (see $evidence/enum-negative.txt)"
fi
ok "enum-negative.txt written (every unknown literal throws, documented literals pass, escape hatch works)"

echo "T55 OK (evidence in $evidence)"
